            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if xroot == yroot:
            return False
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        else:
            parent[yroot] = xroot
            if rank[xroot] == rank[yroot]:
                rank[xroot] += 1
        return True

    # Sort roads by weight
    sorted_roads = sorted(roads, key=lambda x: x[2])

    parent = list(range(n))
    rank = [1] * n
    total_cost = 0
