    for u, v, w in sorted_roads:
        if union(parent, rank, u, v):
            total_cost += w
            edges_used += 1
            if edges_used == n - 1:
                break

    # Check if all cities are connected
    root = find(parent, 0)
    for i in range(1, n):
        if find(parent, i) != root:
            return -1

