def solve(n, edges):
    # Initialize parent array for Union-Find
    parent = list(range(n))

    # Find root of a node with path compression
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    # Union two sets
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Count unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)
