def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Check if all cities are connected
    visited = [False] * n
    stack = [0]
    visited[0] = True
    while stack:
        node = stack.pop()
        for neighbor, _ in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)

    if not all(visited):
        return -1

    # Kruskal's algorithm
    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:
                edges.append((w, u, v))

    edges.sort()
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
