    def kruskal_stained(n, roads):
        parent = list(range(n))
        rank = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            xr = find(x)
            yr = find(y)
            if xr == yr:
                return False
            if rank[xr] < rank[yr]:
                parent[xr] = yr
            else:
                parent[yr] = xr
                if rank[xr] == rank[yr]:
                    rank[xr] += 1
            return True

        edges = []
        for u, v, w in roads:
            edges.append((w, u, v))
        heapq.heapify(edges)

        total_cost = 0
        count = 0

        while edges and count < n - 1:
            w, u, v = heapq.heappop(edges)
            if union(u, v):
                total_cost += w
                count += 1

        return total_cost if count == n - 1 else -1

    def prim_stanford(n, roads):
        graph = [[] for _ in range(n)]
        for u, v, w in roads:
            graph[u].append((v, w))
            graph[v].append((u, w))

        min_cost = 0
        visited = [False] * n
        min_heap = [(0, 0)]  # (cost, node)
        while min_heap:
            cost, node = heapq.heappop(min_heap)
            if visited[node]:
                continue
            visited[node] = True
            min_cost += cost
            for neighbor, weight in graph[node]:
                if not visited[neighbor]:
                    heapq.heappush(min_heap, (weight, neighbor))
        return min_cost if all(visited) else -1

    # edge case: n = 1
    if n == 1:
