from collections import deque

def solve(grid, start, goal):
    rows = [len(r) for r in grid]
    if not rows or rows.count(rows[0]) != len(rows):
        return []
    if start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]):
        return []
    if goal[0] < 0 or goal[0] >= len(grid) or goal[1] < 0 or goal[1] >= len(grid[0]):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([(start, [start])])
    visited.add(start)

    while queue:
        current, path = queue.popleft()
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in visited:
                if (r, c) == goal:
                    return path + [(r, c)]
                visited.add((r, c))
                queue.append(((r, c), path + [(r, c)]))
    return []
